/** The origin of the instance's setup token: configured by the operator, or generated by the host and logged once. */
export type SetupTokenSource = 'configured' | 'generated';

/** What `GET ./api/status` reports for an instance that is not yet set up. */
export interface SetupStatus {
  readonly tokenSource: SetupTokenSource;
  readonly minimumPasswordLength: number;
}

/** The body of `POST ./api/root`. */
export interface CreateRootRequest {
  readonly token: string;
  readonly userName: string;
  readonly email?: string;
  readonly password: string;
}

/** The root administrator the instance created. */
export interface CreatedRoot {
  readonly tenantId: string;
  readonly principalId: string;
  readonly userName: string;
}

/** The problem details the server answers a refused request with. */
export interface ProblemDetail {
  readonly title?: string;
  readonly detail?: string;
}

export type GetStatusResult =
  | { readonly kind: 'ok'; readonly status: SetupStatus }
  | { readonly kind: 'notFound' }
  | { readonly kind: 'error' };

export type CreateRootResult =
  | { readonly kind: 'created'; readonly root: CreatedRoot }
  | { readonly kind: 'invalid'; readonly problem: ProblemDetail }
  | { readonly kind: 'forbidden'; readonly problem: ProblemDetail }
  | { readonly kind: 'notFound' }
  | { readonly kind: 'rateLimited'; readonly problem: ProblemDetail }
  | { readonly kind: 'failed' };

const STATUS_URL = './api/status';
const ROOT_URL = './api/root';

async function readProblem(response: Response): Promise<ProblemDetail> {
  try {
    const body = (await response.json()) as ProblemDetail | null;
    return {
      ...(typeof body?.title === 'string' ? { title: body.title } : {}),
      ...(typeof body?.detail === 'string' ? { detail: body.detail } : {}),
    };
  } catch {
    return {};
  }
}

/** Reads whether the instance accepts setup and where its token comes from. */
export async function getStatus(): Promise<GetStatusResult> {
  try {
    const response = await fetch(STATUS_URL, { headers: { accept: 'application/json' } });
    if (response.status === 404) {
      return { kind: 'notFound' };
    }
    if (!response.ok) {
      return { kind: 'error' };
    }
    return { kind: 'ok', status: (await response.json()) as SetupStatus };
  } catch {
    return { kind: 'error' };
  }
}

/** Creates the instance's root administrator with the setup token. */
export async function createRoot(request: CreateRootRequest): Promise<CreateRootResult> {
  try {
    const response = await fetch(ROOT_URL, {
      method: 'POST',
      headers: { accept: 'application/json', 'content-type': 'application/json' },
      body: JSON.stringify(request),
    });
    switch (response.status) {
      case 201:
        return { kind: 'created', root: (await response.json()) as CreatedRoot };
      case 400:
      case 409:
        return { kind: 'invalid', problem: await readProblem(response) };
      case 403:
        return { kind: 'forbidden', problem: await readProblem(response) };
      case 404:
        return { kind: 'notFound' };
      case 429:
        return { kind: 'rateLimited', problem: await readProblem(response) };
      default:
        return { kind: 'failed' };
    }
  } catch {
    return { kind: 'failed' };
  }
}
